/*
  template.sql
  參數化範本：使用變數 `@EXEC_CPT_DATE` 與 `@EXEC_MERCHANT_NO`。
  範例會示範如何用 sp_executesql 傳入參數執行。
*/

-- 範例宣告（執行時由呼叫端提供）
DECLARE @EXEC_CPT_DATE CHAR(8) = '20260501';
DECLARE @EXEC_MERCHANT_NO NVARCHAR(200) = N'基隆區月票';

DECLARE @SQL_String NVARCHAR(MAX);

SET @SQL_String = N'
select T.SELL_TICKET_AMOUNT / P.MONTHLY_PASS_PRICE As 定期票購買人數
,P.MONTHLY_PASS_PRICE As 定期票價格
from TPS_WRITE_OFF_GOVERNMENT_SUBSIDY_SUM_TOTAL T
LEFT JOIN TPS_BM_MONTHLY_PASS P
ON T.MONTHLY_PASS_NAME = P.MONTHLY_PASS_ACCOUNT_NAME
where WRITE_OFF_START_DATE = @EXEC_CPT_DATE
  AND MONTHLY_PASS_NAME = @EXEC_MERCHANT_NO
';

EXEC sp_executesql
  @SQL_String,
  N'@EXEC_CPT_DATE char(8), @EXEC_MERCHANT_NO nvarchar(200)',
  @EXEC_CPT_DATE = @EXEC_CPT_DATE,
  @EXEC_MERCHANT_NO = @EXEC_MERCHANT_NO;

-- 備註：把變數宣告移到外層或改成存放過程參數以供程式呼叫。
